import{_ as e,I as a,o as i,c as s,b6 as d,J as r}from"./chunks/framework.BUXTSoD9.js";const m=JSON.parse('{"title":"تصوير البيانات ولوحات المعلومات","description":"","frontmatter":{},"headers":[],"relativePath":"ar-sa/appendix/5-data/data-visualization.md","filePath":"ar-sa/appendix/5-data/data-visualization.md"}'),n={name:"ar-sa/appendix/5-data/data-visualization.md"};function h(b,t,g,c,p,u){const o=a("ChartTypeSelectorDemo"),l=a("DashboardLayoutDemo");return i(),s("div",null,[t[0]||(t[0]=d('<h1 id="تصوير-البيانات-ولوحات-المعلومات" tabindex="-1">تصوير البيانات ولوحات المعلومات <a class="header-anchor" href="#تصوير-البيانات-ولوحات-المعلومات" aria-label="Permalink to “تصوير البيانات ولوحات المعلومات”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">مقدمة</p><p><strong>رسم بياني جيد يغني عن ألف صفحة من البيانات.</strong> تصوير البيانات هو تحويل الأرقام المجردة إلى تعبيرات بصرية حدسية، مما يتيح للناس فهم القصة الكامنة وراء البيانات في ثوانٍ معدودة. من رسوم Excel البيانية إلى شاشات مراقبة Grafana، التصوير البصري موجود في كل مكان.</p></div><p><strong>ماذا ستتعلم في هذا المقال؟</strong></p><p>بعد إكمال هذا الفصل، ستكتسب:</p><ul><li><strong>اختيار الرسوم البيانية</strong>: اختيار أنسب نوع رسم بياني بناءً على غرض البيانات</li><li><strong>مبادئ التصوير البصري</strong>: إتقان مبادئ التصميم الأساسية لتصوير البيانات</li><li><strong>تصميم لوحات المعلومات</strong>: فهم أنماط تخطيط لوحات المعلومات المختلفة</li><li><strong>بيئة الأدوات</strong>: التعرف على أدوات التصوير البصري السائدة واختيارها</li><li><strong>المزالق الشائعة</strong>: تجنب الرسوم البيانية المضللة والأخطاء الشائعة في التصوير البصري</li></ul><table tabindex="0"><thead><tr><th>الفصل</th><th>المحتوى</th><th>المفاهيم الأساسية</th></tr></thead><tbody><tr><td><strong>الفصل 1</strong></td><td>اختيار نوع الرسم البياني</td><td>المقارنة، الاتجاهات، النسب، التوزيع، العلاقات</td></tr><tr><td><strong>الفصل 2</strong></td><td>مبادئ تصميم التصوير البصري</td><td>نسبة حبر البيانات، الاتساق، القابلية للقراءة</td></tr><tr><td><strong>الفصل 3</strong></td><td>تخطيط لوحة المعلومات</td><td>النظرة العامة، المقارنة، التفصيل، الوقت الفعلي</td></tr><tr><td><strong>الفصل 4</strong></td><td>اختيار الأدوات</td><td>ECharts، D3، Grafana، Metabase</td></tr><tr><td><strong>الفصل 5</strong></td><td>المزالق الشائعة</td><td>قطع محور الإحداثيات، المخططات الدائرية ثلاثية الأبعاد، الإفراط في استخدام الألوان</td></tr></tbody></table><hr><h2 id="_0-الصورة-الشاملة-لماذا-نحتاج-إلى-التصوير-البصري؟" tabindex="-1">0. الصورة الشاملة: لماذا نحتاج إلى التصوير البصري؟ <a class="header-anchor" href="#_0-الصورة-الشاملة-لماذا-نحتاج-إلى-التصوير-البصري؟" aria-label="Permalink to “0. الصورة الشاملة: لماذا نحتاج إلى التصوير البصري؟”">​</a></h2><p>يعالج الدماغ البشري المعلومات البصرية بسرعة أكبر بكثير من معالجة النصوص. يمكن لمخطط خطي أن يجعلك تلاحظ بسرعة أن &quot;المبيعات كانت في تراجع الشهر الماضي&quot;، بينما نفس المعلومات إذا قُدمت في جدول، قد تحتاج إلى مقارنة صفوف تلو الأخرى للتوصل إلى نتيجة.</p><p>القيم الأساسية للتصوير البصري:</p><ul><li><strong>اكتشاف الأنماط</strong>: الاتجاهات، الدورات، والقيم الشاذة تظهر بوضوح في الرسوم البيانية</li><li><strong>دعم اتخاذ القرار</strong>: تمكين غير التقنيين من فهم البيانات والمشاركة في صنع القرار</li><li><strong>كفاءة التواصل</strong>: صورة واحدة تغني عن ألف كلمة، وتقلل من غموض تفسير البيانات</li></ul><div class="tip custom-block"><p class="custom-block-title">التصوير البصري ≠ المظهر الجميل</p><p>الهدف من التصوير البصري هو <strong>نقل المعلومات</strong>، وليس استعراض المهارات. مخطط أعمدة بسيط ولكنه دقيق، أكثر قيمة بكثير من مخطط ثلاثي الأبعاد مبهرج يصعب فهمه.</p></div><hr><h2 id="_1-اختيار-نوع-الرسم-البياني-استخدم-الرسم-الصحيح-لرواية-القصة-الصحيحة" tabindex="-1">1. اختيار نوع الرسم البياني: استخدم الرسم الصحيح لرواية القصة الصحيحة <a class="header-anchor" href="#_1-اختيار-نوع-الرسم-البياني-استخدم-الرسم-الصحيح-لرواية-القصة-الصحيحة" aria-label="Permalink to “1. اختيار نوع الرسم البياني: استخدم الرسم الصحيح لرواية القصة الصحيحة”">​</a></h2><p>الخطوة الأولى في اختيار الرسم البياني ليست &quot;ما الرسم الذي أحبه&quot;، بل &quot;ما المعلومة التي أريد نقلها&quot;. أغراض البيانات المختلفة تتوافق مع أنواع رسوم بيانية مختلفة مثالية.</p>',15)),r(o),t[1]||(t[1]=d('<h3 id="جدول-مرجعي-سريع-لاختيار-الرسوم-البيانية" tabindex="-1">جدول مرجعي سريع لاختيار الرسوم البيانية <a class="header-anchor" href="#جدول-مرجعي-سريع-لاختيار-الرسوم-البيانية" aria-label="Permalink to “جدول مرجعي سريع لاختيار الرسوم البيانية”">​</a></h3><table tabindex="0"><thead><tr><th>غرض البيانات</th><th>الرسم البياني الموصى به</th><th>غير موصى به</th><th>السبب</th></tr></thead><tbody><tr><td>مقارنة الحجم</td><td>مخطط أعمدة، مخطط أشرطة</td><td>مخطط دائري</td><td>العين البشرية أكثر حساسية لفروق الطول من فروق الزوايا</td></tr><tr><td>عرض الاتجاهات</td><td>مخطط خطي، مخطط مساحي</td><td>مخطط أعمدة</td><td>استمرارية الخطوط توحي باستمرارية الزمن</td></tr><tr><td>عرض النسب</td><td>مخطط دائري (≤5 فئات)، مخطط أعمدة مكدس</td><td>مخطط دائري ثلاثي الأبعاد</td><td>المنظور ثلاثي الأبعاد يشوه نسب المساحات</td></tr><tr><td>عرض التوزيع</td><td>مدرج تكراري، مخطط صندوقي</td><td>مخطط خطي</td><td>التوزيع يتطلب رؤية التكرار، وليس الاتجاهات</td></tr><tr><td>عرض العلاقات</td><td>مخطط انتشار، مخطط فقاعي</td><td>مخطط أعمدة</td><td>علاقة متغيرين مستمرين تتطلب فضاءً ثنائي الأبعاد</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">قاعدة قرار بسيطة</p><ul><li><strong>متغير واحد</strong> → مدرج تكراري (توزيع) أو بطاقة رقمية (KPI)</li><li><strong>متغيران</strong> → مخطط خطي (زمن مقابل قيمة) أو مخطط انتشار (قيمة مقابل قيمة)</li><li><strong>فئات متعددة</strong> → مخطط أعمدة (مقارنة) أو مخطط دائري (نسبة، ≤5 فئات)</li><li><strong>أبعاد متعددة</strong> → مخطط رادار أو مخطط إحداثيات متوازية</li></ul></div><hr><h2 id="_2-مبادئ-تصميم-التصوير-البصري-دع-البيانات-تتحدث" tabindex="-1">2. مبادئ تصميم التصوير البصري: دع البيانات تتحدث <a class="header-anchor" href="#_2-مبادئ-تصميم-التصوير-البصري-دع-البيانات-تتحدث" aria-label="Permalink to “2. مبادئ تصميم التصوير البصري: دع البيانات تتحدث”">​</a></h2><p>التصوير البصري الجيد ليس &quot;جميل المظهر&quot;، بل &quot;سهل الفهم&quot;. المبادئ الكلاسيكية التي طرحها إدوارد توفت في كتابه &quot;The Visual Display of Quantitative Information&quot; لا تزال حتى اليوم مرجعًا مهمًا في تصميم التصوير البصري.</p><table tabindex="0"><thead><tr><th>المبدأ</th><th>الشرح</th><th>مثال مخالف</th></tr></thead><tbody><tr><td>نسبة حبر البيانات</td><td>نسبة &quot;الحبر&quot; المستخدم لعرض البيانات في الرسم البياني يجب أن تكون مرتفعة قدر الإمكان</td><td>خطوط شبكة كثيرة، عناصر زخرفية</td></tr><tr><td>تقليل العناصر غير المتعلقة بالبيانات</td><td>إزالة العناصر البصرية التي لا تنقل معلومات</td><td>تأثيرات ثلاثية الأبعاد، ظلال، خلفيات متدرجة</td></tr><tr><td>مقياس متناسق</td><td>محاور الإحداثيات تبدأ من الصفر، التدرجات منتظمة؛ إذا قُطع المحور يجب توضيح ذلك</td><td>المحور Y يبدأ من 95 بدون بيان</td></tr><tr><td>استخدام الألوان بشكل معقول</td><td>استخدام الألوان لترميز المعلومات، وليس للزينة</td><td>ألوان قوس قزح لتمثيل بيانات مرتبة</td></tr><tr><td>تسميات واضحة</td><td>العنوان، تسميات المحاور، الدليل، والوحدات لا غنى عن أي منها</td><td>عدم وجود وحدات، عدم تحديد نطاق زمني</td></tr></tbody></table><h3 id="_2-1-نسبة-حبر-البيانات-data-ink-ratio" tabindex="-1">2.1 نسبة حبر البيانات (Data-Ink Ratio) <a class="header-anchor" href="#_2-1-نسبة-حبر-البيانات-data-ink-ratio" aria-label="Permalink to “2.1 نسبة حبر البيانات (Data-Ink Ratio)”">​</a></h3><blockquote><p>نسبة &quot;الحبر&quot; المستخدم للتعبير عن البيانات في الرسم البياني إلى إجمالي &quot;الحبر&quot; يجب أن تكون مرتفعة قدر الإمكان.</p></blockquote><p>ببساطة: <strong>احذف كل عنصر لا ينقل معلومات</strong>.</p><table tabindex="0"><thead><tr><th>ما يجب حذفه</th><th>ما يجب الاحتفاظ به</th></tr></thead><tbody><tr><td>تأثيرات ثلاثية الأبعاد، ظلال، تدرجات</td><td>نقاط البيانات، تسميات المحاور</td></tr><tr><td>خطوط شبكة غير ضرورية</td><td>خطوط مرجعية رئيسية (مثل القيمة المستهدفة)</td></tr><tr><td>أيقونات زخرفية</td><td>دليل الألوان (عند وجود سلاسل متعددة)</td></tr><tr><td>ألوان خلفية مبهرجة</td><td>عنوان ووحدات واضحة</td></tr></tbody></table><h3 id="_2-2-مبدأ-الاتساق" tabindex="-1">2.2 مبدأ الاتساق <a class="header-anchor" href="#_2-2-مبدأ-الاتساق" aria-label="Permalink to “2.2 مبدأ الاتساق”">​</a></h3><ul><li><strong>اتساق الألوان</strong>: نفس البُعد يُستخدم مع نفس اللون عبر الرسوم البيانية المختلفة، مثل &quot;الإيرادات&quot; دائمًا باللون الأزرق</li><li><strong>اتساق المقياس</strong>: محاور الإحداثيات تبدأ من 0 قدر الإمكان، ما لم يكن هناك سبب وجيه مع توضيح صريح</li><li><strong>اتساق الزمن</strong>: فواصل المحور الزمني يجب أن تكون منتظمة، لا ترسم نقاط زمنية غير متساوية كأنها متساوية</li></ul><h3 id="_2-3-مبدأ-القابلية-للقراءة" tabindex="-1">2.3 مبدأ القابلية للقراءة <a class="header-anchor" href="#_2-3-مبدأ-القابلية-للقراءة" aria-label="Permalink to “2.3 مبدأ القابلية للقراءة”">​</a></h3><ul><li><strong>العنوان يجب أن يذكر الاستنتاج</strong>: ليس &quot;المبيعات الشهرية&quot;، بل &quot;المبيعات في تراجع مستمر منذ 3 أشهر&quot;</li><li><strong>تمييز النقاط المهمة</strong>: إضافة تعليقات عند القيم الشاذة ونقاط التحول لتوجيه انتباه القارئ</li><li><strong>التحكم في كثافة المعلومات</strong>: رسم بياني واحد ينقل 1-2 معلومة أساسية، لا تُثقل كاهله</li></ul><div class="tip custom-block"><p class="custom-block-title">ثلاث قواعد لاستخدام الألوان</p><ol><li><strong>نفس المؤشر بنفس اللون</strong>: الإيرادات باللون الأزرق في جميع الرسوم البيانية، لا تتغير بين الأزرق والأخضر</li><li><strong>البيانات المرتبة بألوان متدرجة</strong>: درجة الحرارة من منخفضة إلى عالية بتدرج أزرق←أحمر، لا تستخدم ألوانًا متقطعة</li><li><strong>مراعاة عمى الألوان</strong>: حوالي 8% من الرجال يعانون من عمى الألوان الأحمر-الأخضر، تجنب استخدام الأحمر والأخضر فقط للتمييز بين المعلومات الحيوية</li></ol></div><hr><h2 id="_3-تخطيط-لوحة-المعلومات-سيناريوهات-مختلفة،-أنماط-مختلفة" tabindex="-1">3. تخطيط لوحة المعلومات: سيناريوهات مختلفة، أنماط مختلفة <a class="header-anchor" href="#_3-تخطيط-لوحة-المعلومات-سيناريوهات-مختلفة،-أنماط-مختلفة" aria-label="Permalink to “3. تخطيط لوحة المعلومات: سيناريوهات مختلفة، أنماط مختلفة”">​</a></h2><p>لوحة المعلومات (Dashboard) هي مجموعة عضوية من رسوم بيانية متعددة. لوحة المعلومات الجيدة ليست مجرد تكديس للرسوم البيانية، بل اختيار نمط التخطيط المناسب بناءً على سيناريو الاستخدام.</p>',19)),r(l),t[2]||(t[2]=d('<h3 id="أربعة-أنماط-تخطيط-شائعة" tabindex="-1">أربعة أنماط تخطيط شائعة <a class="header-anchor" href="#أربعة-أنماط-تخطيط-شائعة" aria-label="Permalink to “أربعة أنماط تخطيط شائعة”">​</a></h3><table tabindex="0"><thead><tr><th>نمط التخطيط</th><th>الهيكل الأساسي</th><th>سيناريو التطبيق</th><th>نقاط التصميم</th></tr></thead><tbody><tr><td>نظرة عامة شاملة</td><td>بطاقات KPI + مخطط اتجاهات + جدول تفاصيل</td><td>تقارير الإدارة اليومية، لوحة العمليات</td><td>المؤشرات الأساسية في الأعلى، رؤية الأرقام الرئيسية بنظرة واحدة</td></tr><tr><td>تحليل مقارن</td><td>تخطيط متناظر يمين-يسار</td><td>اختبار A/B، تحليل فترة مقابل فترة</td><td>الحفاظ على اتساق أبعاد المقارنة، إبراز الفروق</td></tr><tr><td>تحليل تفصيلي</td><td>توسع تدريجي من الملخص إلى التفاصيل</td><td>تحليل المبيعات، تحليل سلوك المستخدمين</td><td>دعم التفاعل بالنقر، التعمق طبقة تلو الأخرى</td></tr><tr><td>مراقبة فورية</td><td>أرقام كبيرة + منحنى فوري + حالة التنبيهات</td><td>شاشة عرض Double Eleven، مراقبة الخوادم</td><td>تحديث تلقائي، خلفية داكنة، مناسبة للعرض على شاشات كبيرة</td></tr></tbody></table><h3 id="_5-مبادئ-لتصميم-لوحة-المعلومات" tabindex="-1">5 مبادئ لتصميم لوحة المعلومات <a class="header-anchor" href="#_5-مبادئ-لتصميم-لوحة-المعلومات" aria-label="Permalink to “5 مبادئ لتصميم لوحة المعلومات”">​</a></h3><ol><li><strong>اسأل أولاً &quot;من يشاهد&quot;</strong>: الرئيس التنفيذي ينظر إلى المؤشرات الاستراتيجية، فريق العمليات ينظر إلى مؤشرات العمليات، المهندسون ينظرون إلى المؤشرات التقنية</li><li><strong>قاعدة الـ 5 ثوانٍ</strong>: يجب أن يفهم المستخدم المعلومات الأساسية للوحة المعلومات في غضون 5 ثوانٍ</li><li><strong>تسلسل المعلومات</strong>: الأهم في الزاوية العلوية اليسرى، والأقل أهمية في الأسفل</li><li><strong>تقليل التمرير</strong>: عرض المحتوى الأساسي في شاشة واحدة، تجنب حاجة المستخدم للتمرير لرؤية البيانات الحيوية</li><li><strong>المساحات الفارغة</strong>: لا تملأ كل شبر، المساحات الفارغة المناسبة تجعل الرؤية أكثر راحة</li></ol><div class="tip custom-block"><p class="custom-block-title">لوحة المعلومات مقابل التقارير</p><ul><li><strong>لوحة المعلومات</strong>: فورية/شبه فورية، تفاعلية، موجهة للمراقبة واتخاذ القرارات السريعة</li><li><strong>التقارير</strong>: تُنشأ دوريًا (يوميًا/أسبوعيًا/شهريًا)، ثابتة، موجهة للتحليل المفصل والأرشفة</li></ul><p>العلاقة بينهما ليست إحلالية، بل تكاملية. لوحة المعلومات تكتشف المشكلات، والتقارير تتعمق في التحليل.</p></div><hr><h2 id="_4-اختيار-الأدوات-من-مكتبات-البرمجة-إلى-منصات-bi" tabindex="-1">4. اختيار الأدوات: من مكتبات البرمجة إلى منصات BI <a class="header-anchor" href="#_4-اختيار-الأدوات-من-مكتبات-البرمجة-إلى-منصات-bi" aria-label="Permalink to “4. اختيار الأدوات: من مكتبات البرمجة إلى منصات BI”">​</a></h2><p>يمكن تقسيم أدوات التصوير البصري إلى ثلاث مستويات: مكتبات رسوم بيانية على مستوى البرمجة، مكتبات رسوم بيانية لتحليل البيانات، ومنصات BI. يعتمد الاختيار على مدى تعقيد المتطلبات، ومتطلبات التفاعل، والقدرات التقنية للفريق.</p><h3 id="_4-1-مكتبات-رسوم-بيانية-على-مستوى-البرمجة" tabindex="-1">4.1 مكتبات رسوم بيانية على مستوى البرمجة <a class="header-anchor" href="#_4-1-مكتبات-رسوم-بيانية-على-مستوى-البرمجة" aria-label="Permalink to “4.1 مكتبات رسوم بيانية على مستوى البرمجة”">​</a></h3><table tabindex="0"><thead><tr><th>الأداة</th><th>اللغة/المنصة</th><th>الميزات</th><th>سيناريو التطبيق</th></tr></thead><tbody><tr><td>ECharts</td><td>JavaScript</td><td>جاهزة للاستخدام، أنواع رسوم بيانية غنية، توثيق عربي وصيني ممتاز</td><td>رسوم بيانية مدمجة في أنظمة الأعمال</td></tr><tr><td>D3.js</td><td>JavaScript</td><td>مرنة من المستوى الأدنى، قابلة للتخصيص لأي تأثير بصري</td><td>تصوير بيانات قابل للتخصيص بدرجة عالية</td></tr><tr><td>Chart.js</td><td>JavaScript</td><td>خفيفة وبسيطة، سهلة البدء</td><td>احتياجات رسوم بيانية بسيطة</td></tr><tr><td>Matplotlib</td><td>Python</td><td>مكتبة قياسية للحوسبة العلمية، رسوم بيانية ثابتة</td><td>تحليل البيانات، رسوم بيانية للأبحاث</td></tr><tr><td>Plotly</td><td>Python/JS</td><td>رسوم بيانية تفاعلية، تدعم ثلاثي الأبعاد</td><td>استكشاف البيانات، Jupyter Notebook</td></tr></tbody></table><h3 id="_4-2-منصات-bi-بدون-كود-كود-منخفض" tabindex="-1">4.2 منصات BI (بدون كود/كود منخفض) <a class="header-anchor" href="#_4-2-منصات-bi-بدون-كود-كود-منخفض" aria-label="Permalink to “4.2 منصات BI (بدون كود/كود منخفض)”">​</a></h3><table tabindex="0"><thead><tr><th>الأداة</th><th>التموضع</th><th>الميزة الأساسية</th><th>الفريق المناسب</th></tr></thead><tbody><tr><td>Grafana</td><td>تصوير المراقبة</td><td>دعم جيد لبيانات السلاسل الزمنية، تكامل التنبيهات</td><td>فرع العمليات/SRE</td></tr><tr><td>Metabase</td><td>BI خفيف</td><td>مفتوح المصدر ومجاني، SQL كافٍ لإنشاء الرسوم البيانية</td><td>بناء سريع للفرق الصغيرة والمتوسطة</td></tr><tr><td>Apache Superset</td><td>BI للمؤسسات</td><td>مفتوح المصدر، يدعم مصادر بيانات كبيرة</td><td>الشركات التي تمتلك فريق بيانات</td></tr><tr><td>Tableau</td><td>BI تجاري</td><td>عمليات سحب وإفلات، نتائج تصوير ممتازة</td><td>محللو الأعمال</td></tr><tr><td>Power BI</td><td>BI تجاري</td><td>تكامل جيد مع بيئة مايكروسوفت</td><td>المؤسسات التي تستخدم حزمة مايكروسوفت التقنية</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">نصائح الاختيار</p><ul><li><strong>المطورون لرسوم بيانية مدمجة في المنتج</strong> → ECharts (بيئة صينية/عربية جيدة) أو Chart.js (للسيناريوهات البسيطة)</li><li><strong>محللو بيانات للاستكشاف والتحليل</strong> → Plotly + Jupyter أو Metabase</li><li><strong>شاشة مراقبة العمليات</strong> → Grafana (المعيار الفعلي)</li><li><strong>فريق الأعمال للتحليل الذاتي</strong> → Metabase (مفتوح المصدر) أو Tableau (تجاري)</li><li><strong>عند الحاجة لتخصيص عالٍ</strong> → D3.js (منحنى تعلم حاد، لكنه الأكثر مرونة)</li></ul></div><hr><h2 id="_5-المزالق-الشائعة-هذه-الرسوم-البيانية-تخدعك" tabindex="-1">5. المزالق الشائعة: هذه الرسوم البيانية تخدعك <a class="header-anchor" href="#_5-المزالق-الشائعة-هذه-الرسوم-البيانية-تخدعك" aria-label="Permalink to “5. المزالق الشائعة: هذه الرسوم البيانية تخدعك”">​</a></h2><p>تصوير البيانات سيف ذو حدين: استخدامه الجيد يكشف الحقيقة، واستخدامه السيئ يصنع الأوهام. فيما يلي أكثر مزالق التصوير البصري شيوعًا، وكل من يعمل مع البيانات يجب أن يكون قادرًا على التعرف عليها.</p><h3 id="_5-1-قطع-محور-الإحداثيات" tabindex="-1">5.1 قطع محور الإحداثيات <a class="header-anchor" href="#_5-1-قطع-محور-الإحداثيات" aria-label="Permalink to “5.1 قطع محور الإحداثيات”">​</a></h3><p>تغيير نقطة بداية المحور Y من 0 إلى رقم كبير يجعل الفروق الصغيرة تبدو كتغييرات ضخمة.</p><table tabindex="0"><thead><tr><th>السيناريو</th><th>الفرق الحقيقي</th><th>الإحساس البصري</th></tr></thead><tbody><tr><td>المحور Y يبدأ من 0</td><td>المنتج A 98 نقطة، المنتج B 95 نقطة</td><td>الفرق صغير</td></tr><tr><td>المحور Y يبدأ من 90</td><td>نفس البيانات</td><td>A يبدو أكبر من B بعدة أضعاف</td></tr></tbody></table><p><strong>متى يمكن القطع؟</strong> عندما تكون القيم المطلقة للبيانات كبيرة لكن التغيرات صغيرة (مثل سعر السهم من 100 إلى 105)، القطع يكون مقبولًا، لكن يجب توضيحه بشكل صريح.</p><h3 id="_5-2-فخ-المنظور-في-المخططات-الدائرية-ثلاثية-الأبعاد" tabindex="-1">5.2 فخ المنظور في المخططات الدائرية ثلاثية الأبعاد <a class="header-anchor" href="#_5-2-فخ-المنظور-في-المخططات-الدائرية-ثلاثية-الأبعاد" aria-label="Permalink to “5.2 فخ المنظور في المخططات الدائرية ثلاثية الأبعاد”">​</a></h3><p>المنظور ثلاثي الأبعاد يجعل القطاعات الأقرب للمراقب تبدو أكبر. قطاع بنسبة 25% قد يبدو في المنظور ثلاثي الأبعاد وكأنه 35%.</p><p><strong>الحل</strong>: لا تستخدم أبدًا المخططات الدائرية ثلاثية الأبعاد. استخدم مخططًا دائريًا عاديًا أو مخططًا حلقيًا، أو ببساطة مخطط أعمدة.</p><h3 id="_5-3-الإفراط-في-استخدام-الألوان" tabindex="-1">5.3 الإفراط في استخدام الألوان <a class="header-anchor" href="#_5-3-الإفراط-في-استخدام-الألوان" aria-label="Permalink to “5.3 الإفراط في استخدام الألوان”">​</a></h3><table tabindex="0"><thead><tr><th>الممارسة الخاطئة</th><th>الممارسة الصحيحة</th></tr></thead><tbody><tr><td>استخدام الأحمر والأخضر لتمثيل البيانات</td><td>استخدام ألوان آمنة لعمى الألوان كالأزرق والبرتقالي</td></tr><tr><td>لون مختلف لكل فئة</td><td>نفس السلسلة بتدرجات من نفس درجة اللون</td></tr><tr><td>استخدام الألوان لترميز بيانات مستمرة بدون دليل ألوان</td><td>دائمًا قدم دليل ألوان وتسميات رقمية</td></tr><tr><td>تباين غير كافٍ بين لون الخلفية ولون البيانات</td><td>تأكد من تلبية مستوى WCAG AA للتباين</td></tr></tbody></table><h3 id="_5-4-أخطاء-شائعة-أخرى" tabindex="-1">5.4 أخطاء شائعة أخرى <a class="header-anchor" href="#_5-4-أخطاء-شائعة-أخرى" aria-label="Permalink to “5.4 أخطاء شائعة أخرى”">​</a></h3><table tabindex="0"><thead><tr><th>المزلق</th><th>المشكلة</th><th>الإصلاح</th></tr></thead><tbody><tr><td>محور Y مزدوج</td><td>مؤشران غير مرتبطين يشتركان في المحور X، مما يوحي بعلاقة سببية</td><td>فصلهما إلى رسمين بيانيين، أو التوضيح صراحةً بعدم وجود علاقة سببية</td></tr><tr><td>تضليل المساحة</td><td>استخدام نصف القطر بدلاً من المساحة لتمثيل القيم</td><td>عندما تتضاعف القيمة تتضاعف المساحة، وليس نصف القطر</td></tr><tr><td>محور زمني غير منتظم</td><td>مسافات يناير ومارس وديسمبر متساوية</td><td>ترتيب حسب النسب الزمنية الفعلية</td></tr><tr><td>فئات كثيرة جدًا</td><td>مخطط دائري به 15 قطاعًا</td><td>أكثر من 5 فئات استخدم مخطط أعمدة أو ادمج في &quot;أخرى&quot;</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">المبادئ الأخلاقية للتصوير البصري</p><p>الهدف من التصوير البصري هو <strong>المساعدة على الفهم</strong>، وليس <strong>التلاعب بالإدراك</strong>. في كل مرة تنشئ فيها رسمًا بيانيًا، اسأل نفسك:</p><ul><li>لو كنت القارئ، هل سيجعلني هذا الرسم أتوصل إلى استنتاجات خاطئة؟</li><li>هل أخفيت بيانات غير مواتية؟</li><li>هل تعرض المحاور والنسب والألوان البيانات بشكل عادل؟</li></ul></div><hr><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to “الخلاصة”">​</a></h2><p>تصوير البيانات هو &quot;الميل الأخير&quot; في نقل قيمة البيانات. مهما كان التحليل جيدًا، إذا لم يُفهم بشكل صحيح، فكأنه لم يُجرَ أصلاً.</p><p>نستعرض النقاط الرئيسية لهذا الفصل:</p><ol><li><strong>اختيار الرسم البياني الصحيح</strong>: اختيار نوع الرسم البياني بناءً على غرض البيانات (مقارنة، اتجاهات، نسب، توزيع، علاقات)</li><li><strong>مبادئ التصميم</strong>: نسبة حبر بيانات عالية، الاتساق، والقابلية للقراءة هي المبادئ الأساسية الثلاثة</li><li><strong>تخطيط لوحة المعلومات</strong>: أربعة أنماط - النظرة العامة، المقارنة، التفصيل، والوقت الفعلي - تغطي معظم السيناريوهات</li><li><strong>اختيار الأدوات</strong>: من ECharts إلى Grafana، اختر بناءً على قدرات الفريق وتعقيد المتطلبات</li><li><strong>تجنب المزالق</strong>: قطع محور الإحداثيات، المخططات الدائرية ثلاثية الأبعاد، والإفراط في استخدام الألوان هي أكثر أساليب التضليل شيوعًا</li></ol><h2 id="قراءة-إضافية" tabindex="-1">قراءة إضافية <a class="header-anchor" href="#قراءة-إضافية" aria-label="Permalink to “قراءة إضافية”">​</a></h2><ul><li><a href="https://www.edwardtufte.com/tufte/books_vdqi" target="_blank" rel="noreferrer">The Visual Display of Quantitative Information</a> - كتاب إدوارد توفت الكلاسيكي عن التصوير البصري</li><li><a href="https://echarts.apache.org/zh/index.html" target="_blank" rel="noreferrer">توثيق ECharts الرسمي</a> - أشهر مكتبة رسوم بيانية صينية</li><li><a href="https://d3js.org/" target="_blank" rel="noreferrer">D3.js</a> - مكتبة تصوير بصري قوية من المستوى الأدنى</li><li><a href="https://grafana.com/" target="_blank" rel="noreferrer">Grafana</a> - المعيار الفعلي لتصوير المراقبة</li><li><a href="https://www.data-to-viz.com/" target="_blank" rel="noreferrer">From Data to Viz</a> - شجرة قرار لاختيار نوع الرسم البياني</li><li><a href="https://colorbrewer2.org/" target="_blank" rel="noreferrer">ColorBrewer</a> - أداة أنظمة ألوان آمنة لعمى الألوان</li></ul>',35))])}const f=e(n,[["render",h]]);export{m as __pageData,f as default};
